def _add_to_dp(sums_by_k, sum_to_ks, x, n):
    """Update sums_by_k and sum_to_ks by adding x."""
    # Iterate backwards to avoid using x multiple times
    for k in range(n, -1, -1):
        if not sums_by_k[k]:
            continue
        new_sums = set()
        for s in sums_by_k[k]:
            new_s = s + x
            new_sums.add(new_s)
            # Update sum_to_ks
            if new_s not in sum_to_ks:
                sum_to_ks[new_s] = set()
            sum_to_ks[new_s].add(k + 1)
        
        sums_by_k[k+1] = sums_by_k[k+1].union(new_sums)

def _check_add_valid_fast(sums_by_k, sum_to_ks, x, n):
    """
    Check validity using sum_to_ks.
    """
    for k in range(1, n + 2):
        if not sums_by_k[k-1]:
            continue
        for s in sums_by_k[k-1]:
            new_s = s + x
            # If new_s is already in sum_to_ks, check if it's only associated with k
            if new_s in sum_to_ks:
                existing_ks = sum_to_ks[new_s]
                # If any existing k' is not k, collision
                # Note: k is the target cardinality for this new sum.
                # The new sum is added to cardinality k.
                # So if existing_ks contains any k' != k, it's invalid.
                for k_prime in existing_ks:
                    if k_prime != k:
                        return False
            # If new_s not in sum_to_ks, it's a new sum, no collision with existing.
    return True

def construct():
    t_start = time.time()
    deadline = t_start + DEADLINE_SECONDS
    
    best_set = []
    best_size = 0
    
    # Heuristic: Prefer candidates that minimize the "spread" or keep sums compact.
    # We'll use a greedy approach with multiple random restarts.
    
    for attempt in range(500):
        if time.time() > deadline:
            break
            
        if attempt == 0:
            candidates = list(range(1, 257))
        elif attempt == 1:
            candidates = list(range(256, 0, -1))
        else:
            candidates = list(range(1, 257))
            random.shuffle(candidates)
        
        current = []
        n = 0
        sums_by_k = [set() for _ in range(61)] # Max size 60
        sums_by_k[0].add(0)
        sum_to_ks = defaultdict(set)
        sum_to_ks[0].add(0)
        
        for x in candidates:
            if time.time() > deadline:
                break
            if len(current) >= 60:
                break
            
            # Check if x can be added
            if _check_add_valid_fast(sums_by_k, sum_to_ks, x, n):
                # Add x
                current.append(x)
                n += 1
                _add_to_dp(sums_by_k, sum_to_ks, x, n)
        
        if len(current) > best_size:
            best_size = len(current)
            best_set = current[:]
            # If we found a very good one, we might break early?
            # But let's keep searching for max.
            
    return list(best_set)
